class AtCoder {

    final int N;
    String[] ss;

    AtCoder(FastScanner sc) {
        N = sc.nextInt();
        ss = new String[N];
        for (int i = 0; i < N; i++) {
            ss[i] = sc.next();
        }
    }

    void solve(PrintWriter out) {
        for (int i = 0; i < N - 1; i++) {
            int j = ss[i].length() - 1;
            if (ss[i].charAt(j) != ss[i + 1].charAt(0)) {
                out.println("No");
                return;
            }
        }
        Arrays.sort(ss);
        for (int i = 0; i < N - 1; i++) {
            if (ss[i].equals(ss[i + 1])) {
                out.println("No");
                return;
            }
        }
        out.println("Yes");
    }

}

