		new Thread(null, new Main(), "", Runtime.getRuntime().maxMemory()).start();
	}

	Main() {
		sc = new FastScanner();
		out = new PrintWriter(System.out);
	}

	private void init() throws Exception {
		int n = sc.nextInt();
		sum = 1;
		for(int i=0;i<n;i++){
			long a = sc.nextLong();
			sum *= a;
			if(sum==0) break;
			if(sum>1000000000000000000L || sum < 0){
				sum = -1;
				break;
			}
		}
	}

	private void solve() throws Exception{
		out.println(sum);
	}

	public void run() {
		int status = 0;
		try{
			init();
			sc.close();
			solve();
		} catch (Exception e) {
			status = 1;
			e.printStackTrace();
		} finally {
			sc.close();
		}
		out.flush();
		out.close();
		System.exit(status);
	}
}

