					ary[i - 1] = temp;

					numSwap++;
					flag = true;
				}
			}
		}

		for (int i = 0; i < N; i++)
		{
			System.out.print(ary[i]);
			if (i < N - 1)
			{
				System.out.print(" ");
			}
		}
		System.out.println("");
