public static boolean triangle(int i,int[][] t){
int max=Math.max(Math.max(t[i][0],t[i][1]),t[i][2]);
int res=Math.min(Math.min(Math.hypot(t[i][0],t[i][1]),Math.hypot(t[i][0],t[i][2])),Math.hypot(t[i][2],t[i][1]));
if(res==max){return true;}
else{return false;}
}
}

