        for(int t = 1; t <= T; t++)
        {
            int n = in.nextInt();
            long a[] = in.nextLongArray(n);
            int pt=1,count=0;
            for(int i=0;i<n;i++){
                if(a[i]==pt){
                    count++;
                    pt++;
                }
            }
            count = n-count;
            if(count==n) out.write("-1\n");
            else out.write(count+"\n");
        }
