public class Main {
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    int k = sc.nextInt();
    int[] nums = new int[n];
    int[] dp = new int[n + 1];
    for (int i = 0; i < n; i++) {
      nums[i] = sc.nextInt();
    }
    sc.close();
    Arrays.fill(dp, 10000000);
    dp[0] = 0;
    for (int i = 0; i < n; i++) {
      for (int j = 1; j <= k && i + j < n; j++) {
          dp[i + j] = Math.min(dp[i + j], dp[i] + Math.abs(nums[i] - nums[i + j]));
      }
    }
    System.out.println(dp[n - 1]);
  }
}

