        int n = sc.nextInt();

        boolean[] isExist = new boolean[100];
        for (int i = 0; i < n; i++) {
            int p = sc.nextInt()-1;
            isExist[p] = true;
        }

        int ans = 0;
        for (int i = 0; i <= 50; i++) {
            if (x-i >= 0 && !isExist[x-i]) {
                ans = x-i+1;
                break;
