    private static void solve(FastScanner in, PrintWriter out){
        int n = in.nextInt();
        int k = in.nextInt();
        int a[] = new int[n];
        for(int i=0;i<n;i++){
            a[i] = in.nextInt();
        }
        Arrays.sort(a);
        long sum=0L;
        for(int i=0;i<n-k;i++) sum+=a[i];
        out.println(sum);
    }

    /************* SOLUTION ENDS HERE **********/
}

