        for (int i = 0; i < n; i++) {
            int left = Math.min(a[i], b[i]);
            sum += left;
            a[i] -= left;
            b[i] -= left;
            int right = Math.min(a[i + 1], b[i]);
            sum += right;
            a[i + 1] -= right;
            b[i] -= right;
        }
        System.out.println(sum);
    }
}

