		InputReader scn = new InputReader(System.in);
		OutputWriter out = new OutputWriter(System.out);
		String s = scn.next();
		String[] str = s.split("");
		boolean check = CountFrequencies(str);
		if (check) {
			out.println("Yes");
		} else {
			out.println("No");
