		for (int i=0;i<M;i++) {
			int p = sc.nextInt()-1;
			String S = sc.next();

			if (S.equals("AC")) {
				solved[p] = true;
			} else { // S.equals("WA")
				if (!solved[p]) penalty++;
			}
		}

		int accepted = 0;
		for (int i=0;i<N;i++) {
			if (solved[i]) accepted++;
		}
		System.out.println(accepted+" "+penalty);
	}
}

