		ans = Math.min(a * xy[0] + b * xy[0], c * xy[0] * 2);

		if (x != y) {
			int t = xy[1] - xy[0];
			ans += Math.min(map.get(xy[1]) * t, c * t * 2);
		}

		System.out.println(ans);

	}
}

