                min = 101;
                boolean isNum2 = false;
                for (int i = start; i < n; i++) {
                    end = i;
                    if (h[i] > 0) {
                        isNum = true;
                        isNum2 = true;
                    }
                    if (h[i] == 0 && isNum2) {
                        break;
                    }
                    end = i + 1;
