    public long gcd(long a, long b) {
        if (b==0) return a;
        return gcd(b,a%b);
    }

    public long lcm(long a, long b) {
        return (a*b) / gcd(a,b);
    }

    public long f(long a, long b, long c) {
        long n =  b / c;
        n -= a / c;
        return n;
    }

