		int ans = 0 ;
		for(int i = 1 ; i <= N ;i ++) {
			if(i < 10 || (100 <= i &&  i <= 999)|| (10000 <= i &&  i <= 99999)) {
				ans ++ ;
			}
		}
		return ans ;
	}
