            mm_s = input % HH_TIME;
            if (mm_s >= MM_TIME) {
                mm = mm_s / MM_TIME;
                ss = mm_s % MM_TIME;
            } else {
                ss = mm_s;
            }
        } else {
            mm = input / MM_TIME;
            ss = input % MM_TIME;
        }
        return hh.toString() + ":" + mm.toString() + ":" + ss.toString();
    }
}

