				for(int j = 0; j < B + 1; j++) {
					int sumj = sumi + 100 * j;
					if(!(sumj > X)) {
						if(!((X - sumj) / 50 > C)) {
							pattern++;
						}
					} else {
						break;
					}
				}
			} else {
				break;
			}
		}
		System.out.println(pattern);
	}

}

