        int l[] = new int[n];
        int GCD = 0;
        for (int i = 0; i < n; i++) {
            int tmp = sc.nextInt();
            if (i == 0){
                GCD = tmp;
                continue;
            }
            GCD = gcd(GCD, tmp);
        }
        int cnt = 0;
        while (GCD % 2 == 0) {
            GCD/=2;
            cnt++;
        }


        System.out.println(cnt);
    }
}

