	}

	private static int countExponent2(int x) {
		int exponent2 = 0;
		// 引数に対して何回、２で割る処理が実行できるかを調べる
		while(x%2 == 0) {
			x = x/2;
			exponent2++;
		}

		return exponent2;
	}

}

