        int[] h = new int[n];
        String result = "Yes";

        for( int i = 0; i < n; i++ ) {
            h[i] = sc.nextInt();
            if( i != 0 ) {
                if( h[i] - h[i - 1] <= -1 ) {
//                    System.out.println( "h : " + h[i] );
                    h[i - 1] = h[i - 1] - 1;
                    if( h[i] - h[i - 2] <= -1 ) {
                        result = "No";
                        break;
                    }
                }
            }
        }

        System.out.println( result );

        sc.close();
    }
}

