        FastScanner fs = new FastScanner();
        long t = fs.nextLong();
        long a = fs.nextLong();
        long k = fs.nextLong();

        if (k >= t) {
            k = k - t;
            t = 0;

            if (k > 0) {
                a = a - k;
            }
        } else {
