		    String op = line.split(" ")[1];
		    int b  = Integer.parseInt(line.split(" ")[2]);

		    if("?".equals(op)) break;

		    if ("+".equals(op)) {
			    System.out.println(a + b);

		    } else if("-".equals(op)) {
			    System.out.println(a - b);

		    } else if("*".equals(op)) {
			    System.out.println(a * b);

		    } else if("/".equals(op)) {
			    System.out.println((int)(a / b));

		    }
	    }
	}
}

