        dp[0] = 1;
        dp[1] = 1;

        for (int i = 0; i < m; i++) {
            dp[list.get(i)] = -1;
        }

        for (int j = 2; j <= n; j++) {
            if (dp[j] != -1 && dp[j - 1] != -1 && dp[j - 2] != -1) {
                dp[j] = (dp[j - 1] + dp[j - 2]) % INF;
            } else if (dp[j] != -1 && dp[j - 1] == -1) {
                dp[j] = (dp[j - 2]);
            } else if (dp[j] != -1 && dp[j - 2] == -1) {
                dp[j] = (dp[j - 1]);
            }


        }
        if (dp[n] == -1) {
            System.out.println(0);
        } else {
            System.out.println(dp[n] % INF);
        }
    }
}

