		int[] A = new int[n];

		for (int i = 0; i < n; i++) {
			A[i] = scan.nextInt();
		}

		printArray(A);
		for (int i = 1; i < n; i++) {
			int key = A[i];
			int j;
			for (j = i - 1; j >= 0 && A[j] > key; j--) {
