class Solver {            
    StringBuilder out=new StringBuilder(100);
    FastReader in=new FastReader();
    public long pow(long a, long b){
        if(b==0)return 1;
            long ans=pow(a,b/2);
            ans*=ans;
            ans%=mod;
        if(b%2==1){
            ans*=a;
            ans%=mod;
        }
        return ans;
    }

    public int[] getIntArray(int n){
        int arr[]=new int[n];
        for(int i=0;i<n;i++){
            arr[i]=in.nextInt();
        }
        return arr;
    }

    int  mod=(int)(1e9 + 7);

    public void solve(){
        int n=in.nextInt();
        int arr[]=getIntArray(n);
        int dp[]=new int[n+1];
        for(int i=1;i<n;i++){
            int pre=20000;
            if(i>0){
                pre=dp[i-1]+Math.abs(arr[i]-arr[i-1]);
            }
            int prepre=20000;
            if(i>1){
                prepre=dp[i-2]+Math.abs(arr[i]-arr[i-2]);
            }
            dp[i]=Math.min(pre, prepre);
        }
        out.append(dp[n-1]);
    }
    public void run(){
        int t=1;
        for(int i=0;i<t;i++){
            solve();
            out.append('\n');
        }
        System.out.println(out);
    }
}





