    }

    static class TaskB {
        public void solve(int testNumber, InputReader in, PrintWriter out) {
            int n = in.nextInt();
            int m = in.nextInt();
            int x = in.nextInt();

            int[] a = in.nextIntArray(m);

            int cnt1 = 0;
            int cnt2 = 0;
            for (int i = 0; i < m; i++) {
                if (a[i] < x) cnt1++;
                if (a[i] > x) cnt2++;
            }

            out.println(Math.min(cnt1, cnt2));
        }

    }

    static class InputReader {
