public class Main {
    public static void main(String[] args) {
        Scanner scanner= new Scanner(System.in);
        long min = scanner.nextLong();
        long max = scanner.nextLong();
        long divider1 = scanner.nextLong();
        long divider2 = scanner.nextLong();

        long min1 = min / divider1;
        long max1 = max / divider1;
        long min2 = min / divider2;
        long max2 = max / divider2;

        long crossDivider = lcm(divider1, divider2);
        long crossmin = min / crossDivider;
        long crossmax = max / crossDivider;

        long mm = max1 -min1;
        long nn = max2 - min2;
        long cc = crossmax - crossmin;
        System.out.println((max - min) -(mm + nn) + cc + 1);
    }
    private static long lcm(long m, long n) {
        return m * n / gcd(m, n);
    }

    private static long gcd(long m, long n) {
        if(m < n) return gcd(n, m);
        if(n == 0) return m;
        return gcd(n, m % n);
    }
}

import java.util.*; 
import java.io.*;

public class Main {
	static int n = 0 , k = 0; 
	static int a[] = new int[(int) 1e5 + 7];
	static int dp[] = new int[(int) 1e5 + 7]; 
	public static int fun(int ind) {
		if(ind == n-1) return 0; 

		else if(dp[ind] != -1) return dp[ind]; 

		else {
		         int max = (int) 1e5 + 7; 

		         for(int i = 1; i<=k; i++) {
			          if(ind + i < n)
			              max = Math.min(max, Math.abs(a[ind + i] - a[ind]) + fun(ind + i)); 
		        }
		        return dp[ind] = max; 
		}
	}
	public static void solve(InputReader in) {
		n = in.readInt(); 
		k = in.readInt(); 
        for(int i = 0; i<n; i++) {
        	a[i] = in.readInt(); 
        }
        Arrays.fill(dp, -1); 
        System.out.println(fun(0)); 
	}
	public static void main(String[] args) {
		InputReader in = new InputReader(System.in); 
		int t = in.readInt(); 
		while(t-- > 0) {
			solve(in); 
		}
	}
}

class InputReader{
	private InputStream stream;
	private byte[] buf = new byte[1024];
	private int curChar;
	private int numChars;
	private SpaceCharFilter filter;

	 public InputReader(InputStream stream) {
		this.stream = stream;
	}

     public int read() {
		if (numChars == -1)
			throw new InputMismatchException();
		if (curChar >= numChars) {
			curChar = 0;
			try {
				numChars = stream.read(buf);
			} catch (IOException e) {
				throw new InputMismatchException();
			}
			if (numChars <= 0)
				return -1;
		}
		return buf[curChar++];
	}

     public int readInt() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		int res = 0;
		do {
			if (c < '0' || c > '9')
				throw new InputMismatchException();
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

     public String readString() {
		int c = read();
		while (isSpaceChar(c))
			c = read();
		StringBuilder res = new StringBuilder();
		do {
			res.appendCodePoint(c);
			c = read();
		} while (!isSpaceChar(c));
		return res.toString();
	}

     public long readLong() {
		int c = read();
		while (isSpaceChar(c)) {
			c = read();
		}
		int sgn = 1;
		if (c == '-') {
			sgn = -1;
			c = read();
		}
		long res = 0;
		do {
			if (c < '0' || c > '9') {
				throw new InputMismatchException();
			}
			res *= 10;
			res += c - '0';
			c = read();
		} while (!isSpaceChar(c));
		return res * sgn;
	}

     public boolean isSpaceChar(int c) {
		if (filter != null)
			return filter.isSpaceChar(c);
		return c == ' ' || c == '\n' || c == '\r' || c == '\t' || c == -1;
	}

     public String next() {
		return readString();
	}

     public interface SpaceCharFilter {
		public boolean isSpaceChar(int ch);
	}
}

import java.util.Scanner;
import java.util.List;
import java.util.ArrayList;
import java.util.Collections;

public class Main {
  public static int result(List<Integer> A, List<Integer> B) {
    int result = 0;
    int n = B.size();
    for (int i = 0; i < n; i++)
      if (A.get(i) > B.get(i)) {
        result += B.get(i);
        A.set(i, A.get(i) - B.get(i));
        B.set(i, 0);
      } else {
        result += A.get(i);
        B.set(i, B.get(i) - A.get(i));
        A.set(i, 0);
        if (A.get(i + 1) > B.get(i)) {
          result += B.get(i);
          A.set(i + 1, A.get(i + 1) - B.get(i));
        } else {
          result += A.get(i + 1);
          A.set(i + 1, 0);
        }
      }
    return result;
  }
  public static void main(String[] args) {
    Scanner sc = new Scanner(System.in);
    int n = sc.nextInt();
    List<Integer> A = new ArrayList<Integer>();
    List<Integer> B = new ArrayList<Integer>();
    for (int i = 0; i < n + 1; i++)
      A.add(sc.nextInt());
    for (int i = 0; i < n; i++)
      B.add(sc.nextInt());
    int result1 = Main.result(A, B);
    Collections.reverse(A);
    Collections.reverse(B);
    int result2 = Main.result(A, B);
    System.out.println(result1 > result2 ? result1 : result2);
  }
}

