	static void sort( int A[] )
	{
		int v, j;
		for( int i = 1 ; i < A.length ; i++ )
		{
			putArray(A);
			v = A[i];
			for( j = i-1 ; 0<=j && v<A[j] ; j-- )
				A[j+1] = A[j];
			A[j+1] = v;
		}
		return;
	}
	static void putArray( int A[] )
	{
		for( int i = 0 ; i < A.length ; i++ )
		{
			if( i==A.length-1 )
				System.out.print( A[i]+"\n" );
			else
				System.out.print( A[i]+" " );
		}
		return;
	}
