		int[] X = new int[N];
		for (int i = 0; i < N; i++) {
			X[i] = sc.nextInt();
			total += X[i];
		}
		if ((10*total/N)%10 < 5) {
			av = total/N;
		} else {
			av = total/N + 1;
		}
		for (int x : X) {
			int p = x - av;
			pow += p*p;
		}
		System.out.println(pow);
	}
}

