            result = "AMBIGUOUS";
        }
        System.out.println(result);
    }
    public static boolean isYY(String string) {

        boolean flag = false;
        if (string.matches("[0-9]{2}")) {
            flag = true;
        }
        return flag;
    }
    public static boolean isMM(String string) {

        boolean flag = false;
        if (string.matches("0[1-9]{1}") || string.matches("1[0-2]{1}")) {
            flag = true;
        }
        return flag;
    }
}

