	static class TaskX {
		public void solve(int testNumber, InputReader in, PrintWriter out) {

			char[] s = in.nextString().toCharArray();
			Set<String> t = new HashSet<>();
			t.add("dream");
			t.add("dreamer");
			t.add("erase");
			t.add("eraser");

			while (s.length > 0) {
				boolean isMatch = false;
				for (String str : t) {
					int tlen = str.length();
					char[] tar = str.toCharArray();
					int slen = s.length;
					boolean isSame = true;
					for (int i = slen - tlen; i < slen; i++) {
						if (i < 0) {
							isSame = false;
							break;
						}
						if (s[i] == tar[i - slen + tlen]) {
							continue;
						} else {
							isSame = false;
							break;
						}
					}
					if (isSame) {
						s = Arrays.copyOf(s, slen - tlen);
						isMatch = true;
						break;
					}
				}
				if (!isMatch) {
					out.println("NO");
					return;
				}
			}
			out.println("YES");

		}
	}

