		}for(int j=0; j<N; j++) {
			t[j] = all[j/3];
			x[j] = all[(j-1)/3];
			y[j] = all[(j-2)/3];
		}

		int judge = 0;

		if(x[0] + y[0] <= t[0] && (x[0]+y[0]-t[0])%2 == 0) {
			judge += 1;
		}else {
			judge += 0;
		}

