public class Main {

	public void run(java.io.InputStream in, java.io.PrintStream out) {
		final java.util.Scanner sc = new java.util.Scanner(in);
		int[][] a;
		int[][] b;
		int[][] r;
		int n, m, l;

		n = sc.nextInt();
		m = sc.nextInt();
		l = sc.nextInt();
		a = new int[n][m];
		b = new int[m][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < m; ++j) {
			a[i][j] = sc.nextInt();
		}
		for (int i = 0; i < m; ++i)
		for (int j = 0; j < l; ++j){
			b[i][j] = sc.nextInt();
		}

		r = new int[n][l];
		for (int i = 0; i < n; ++i)
		for (int j = 0; j < l; ++j) {
			r[i][j] = 0;
			for (int k = 0; k < m; ++k) {
				r[i][j] += a[i][k] * b[k][j];
			}
		}

		for (int i = 0; i < n; ++i) {
			for (int j = 0; j < l; ++j) {
				out.print(r[i][j]);
				if (j + 1 == l) out.println();
				else out.print(" ");
			}
		}

		sc.close();
	}

