public class Main {
    public static void main(String[] args){
        Scanner sc = new Scanner(System.in);
        int N = sc.nextInt();
        int M = sc.nextInt();
        Integer[] Ms = new Integer[M];
        List<Integer> MsList = Arrays.asList(Ms);
        for (int m = 0; m < M; m++){
            Ms[m] = sc.nextInt();
        }
        long[] memo = new long[N+1];
        for (int n = 1; n <= N; n++){
            if (n == 1) {
                if (MsList.contains(1)){memo[1] = 0;}
                else {memo[1] = 1;}
                continue;
            }
            if (n == 2){
                if (MsList.contains(2)){memo[2] = 0;}
                else if (Arrays.asList(Ms).contains(1)){memo[2] = 1;}
                else {memo[2] = 2;}
                continue;
            }
            boolean inN = MsList.contains(n);
            if ((inN) && (MsList.contains(n-1))){
                break;
            }
            if (inN) {
                continue;
            }
            memo[n] = (memo[n-2] + memo[n-1])%1000000007;
        }
        System.out.println(memo[N]%1000000007);
      }
}

public class Main {
	public static void main(String[] args) {
		Scanner sc = new Scanner(System.in);

		int N = sc.nextInt();
		int[] A = new int[N];
		int[] B = new int[N];
		int[] C = new int[N-1];
		for(int i=0;i<N;i++) {
			A[i] = sc.nextInt();
		}
		for(int i=0;i<N;i++) {
			B[i] = sc.nextInt();
		}
		for(int i=0;i<N-1;i++) {
			C[i] = sc.nextInt();
		}

		int satisfact = 0;
		int preNum = 0;

		for(int i=0;i<N;i++) {
			int num = A[i];
			satisfact += B[num - 1];
			if(preNum + 1 == num && preNum != 0) {
				satisfact += C[preNum - 1];
			}
			preNum = num;
		}

		System.out.println(satisfact);

		sc.close();	
	}
}

