	public static int strike(int a[], int b[],int ind) {
		int cap=b[ind];
		if(a[ind]>=cap) {
			a[ind]-=cap;
			return cap;
		}else {
			int res = 0;
			cap-=a[ind];
			res+=a[ind];
			a[ind]=0;
			if(a[ind+1]>=cap) {
				a[ind+1]-=cap;
				return res + cap;
			}else {
				cap=0;
				res += a[ind+1];
				a[ind+1]=0;
				return res;
			}
		}
	}
