        for(int i=0; i<n; i++){
            bl = true;
            while(bl == true){
                if(a[i] % 2 == 0){
                    a[i] /= 2;
                    count++;
                }
                else{
                    bl = false;
                }
            }
        }
        System.out.println(count);
    }
}

